import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../tool/src/manifest.dart';
import '../../tool/src/pack.dart';

const _demoPackDart = '''
// GENERATED by tool/apply_pack.dart from pack/pack.json. Do not edit.
import 'dart:ui';

const packAppName = 'FogCatcher';
const packTagline = 'Walk to clear the fog. Find what it hides.';
const packEventLine = 'Champ de Mars · Demo pack';
final packEventEnd = DateTime.utc(2099, 12, 31, 23, 59, 59);
const packDefaultSiteId = 'champ_de_mars';

abstract final class AppColors {
  static const primary = Color(0xFF29ADFF);
  static const primaryDeep = Color(0xFF065AB5);
  static const ink = Color(0xFF1D2B53);
  static const paper = Color(0xFFFFF1E8);
  static const accent = Color(0xFFFFA300);
  static const alert = Color(0xFFFF004D);
  static const shade = Color(0xFF7E2553);
  static const highlight = Color(0xFFFF77A8);
}
''';

Map<String, dynamic> _pack({Map<String, dynamic> override = const {}}) => {
  'appName': 'Demo',
  'tagline': 'Tag',
  'eventLine': 'Line',
  'eventEnd': '2030-01-02T03:04:05Z',
  'defaultSiteId': 'demo_park',
  'palette': {for (final r in paletteRoles) r: '#123abc'},
  ...override,
};

const _pubspec = '''
name: demo
flutter:
  uses-material-design: true
  assets:
    - assets/brand/
    - assets/sites/old_site/
  fonts:
    - family: X

flutter_launcher_icons:
  adaptive_icon_background: "#000000"

flutter_native_splash:
  color: "#000000"
  android_12:
    color: "#000000"
''';

void main() {
  group('packDart', () {
    final demo =
        jsonDecode(File('pack/pack.json').readAsStringSync())
            as Map<String, dynamic>;

    test('matches the contract for pack/pack.json', () {
      expect(packDart(demo), _demoPackDart);
    });

    test('matches the committed lib/config/pack.g.dart', () {
      expect(packDart(demo), File('lib/config/pack.g.dart').readAsStringSync());
    });

    test('escapes quotes, dollars, backslashes and newlines', () {
      expect(dartString(r"it's $5 \ ok"), r"'it\'s \$5 \\ ok'");
      expect(dartString('a\nb'), r"'a\nb'");
      final out = packDart(_pack(override: {'appName': r"Bob's $app"}));
      expect(out, contains(r"const packAppName = 'Bob\'s \$app';"));
    });

    test('wraps long declarations like dart format', () {
      final out = packDart(_pack(override: {'tagline': 'x' * 70}));
      expect(out, contains("const packTagline =\n    '${'x' * 70}';"));
    });

    test('renders eventEnd in UTC, milliseconds only when set', () {
      expect(
        packDart(_pack(override: {'eventEnd': '2030-01-02T05:04:05+02:00'})),
        contains('DateTime.utc(2030, 1, 2, 3, 4, 5);'),
      );
      expect(
        packDart(_pack(override: {'eventEnd': '2030-01-02T03:04:05.250Z'})),
        contains('DateTime.utc(2030, 1, 2, 3, 4, 5, 250);'),
      );
    });

    test('upper-cases palette hex', () {
      expect(packDart(_pack()), contains('Color(0xFF123ABC)'));
    });

    test('rejects bad palettes, dates and missing fields', () {
      final missing = {for (final r in paletteRoles.skip(1)) r: '#123456'};
      final bad = {...missing, 'primary': 'blue'};
      final extra = {...missing, 'primary': '#123456', 'neon': '#123456'};
      for (final p in [missing, bad, extra]) {
        expect(
          () => packDart(_pack(override: {'palette': p})),
          throwsFormatException,
        );
      }
      expect(
        () => packDart(_pack(override: {'eventEnd': 'soon'})),
        throwsFormatException,
      );
      expect(
        () => packDart(_pack(override: {'appName': ''})),
        throwsFormatException,
      );
    });
  });

  group('manifest', () {
    test('withSiteAssets declares fixed dirs plus one per site', () {
      final out = withSiteAssets(_pubspec, ['demo_park', 'test_site']);
      expect(
        out,
        contains('''
  assets:
    - assets/brand/
    - assets/fonts/
    - assets/tiles/
    - assets/sites/
    - assets/sites/demo_park/
    - assets/sites/test_site/
    - assets/items/
  fonts:
'''),
      );
      expect(out, isNot(contains('old_site')));
      expect(withSiteAssets(out, ['demo_park', 'test_site']), out);
    });

    test('withSiteAssets needs a flutter.assets list', () {
      expect(() => withSiteAssets('name: x\n', []), throwsFormatException);
    });

    test('withBrandColor sets icon and splash colours', () {
      final out = withBrandColor(_pubspec, '#1d2b53');
      expect('"#1D2B53"'.allMatches(out), hasLength(3));
      expect(out, isNot(contains('#000000')));
    });

    test('withSite appends once and siteIds reads back', () {
      final index = encodeIndex(['demo_park']);
      final added = withSite(index, 'test_site');
      expect(siteIds(added), ['demo_park', 'test_site']);
      expect(withSite(added, 'test_site'), added);
      expect(
        added,
        '{\n  "sites": [\n    "demo_park",\n    "test_site"\n  ]\n}\n',
      );
    });
  });
  group('guardSplashStyles', () {
    const raw = '<item name="android:forceDarkAllowed">false</item>';
    const guarded =
        '<item name="android:forceDarkAllowed" tools:targetApi="q">false</item>';

    test('adds the API guard and is idempotent', () {
      expect(guardSplashStyles(raw), guarded);
      expect(guardSplashStyles(guarded), guarded);
    });

    test('committed splash styles keep their API guards', () {
      for (final dir in ['values', 'values-night']) {
        final xml = File(
          'android/app/src/main/res/$dir/styles.xml',
        ).readAsStringSync();
        expect(guardSplashStyles(xml), xml, reason: dir);
      }
    });
  });
}
